import {BLOCK_FORMS,formId,slotShape,cycleForm,formAllowed,formIconPolygons} from './block-forms.mjs';
export function createBlockFormMenu({getItem,onChange,active,materialName,materialColor=()=>'#bca779'}){
 let root=null;
 function mount(){if(root)return;root=document.createElement('aside');root.id='blockFormMenu';root.className='block-form-menu';root.hidden=true;root.setAttribute('role','status');root.setAttribute('aria-live','polite');document.body.append(root)}
 function hide(){if(root)root.hidden=true}
 function show(){const item=getItem();if(!active()||!formAllowed(item)){hide();return false}mount();const id=formId(item.shape),i=BLOCK_FORMS.findIndex(f=>f.id===id);root.replaceChildren();const head=document.createElement('div');head.className='block-form-title';head.textContent=materialName(item)+' · Forme '+(i+1)+' / '+BLOCK_FORMS.length;root.append(head);const row=document.createElement('div');row.className='block-form-strip';for(let j=-3;j<=3;j++){const f=BLOCK_FORMS[(i+j+BLOCK_FORMS.length)%BLOCK_FORMS.length],el=document.createElement('div');el.className='block-form-choice'+(j===0?' current':'');const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('class','block-form-symbol');icon.setAttribute('viewBox','0 0 64 56');icon.setAttribute('aria-hidden','true');for(const face of formIconPolygons(f.id)){const poly=document.createElementNS('http://www.w3.org/2000/svg','polygon');poly.setAttribute('points',face.points);poly.setAttribute('fill',materialColor(item));poly.setAttribute('fill-opacity',String(face.shade));poly.setAttribute('stroke','#18201c');poly.setAttribute('stroke-width','.65');icon.append(poly)}const label=document.createElement('span');label.textContent=f.name;el.append(icon,label);row.append(el)}root.append(row);const foot=document.createElement('div');foot.className='block-form-help';foot.textContent='Alt + molette : forme  •  Relâcher Alt : fermer  •  Rotation automatique à la visée';root.append(foot);root.hidden=false;return true}
 function scroll(delta){const item=getItem();if(!active()||!formAllowed(item)||!delta)return false;item.shape=slotShape(cycleForm(item.shape,delta));onChange(item);show();return true}
 function wheel(e){if(!e.altKey||e.ctrlKey||e.metaKey)return false;if(!scroll(e.deltaY))hide();return true}
 return {show,hide,scroll,wheel};
}
